from __future__ import unicode_literals

import re

from .exceptions import ScfcFixerException, NoSuchManagedObject, NoSuchParameter, NoSuchListParameter, \
    ExactlyOneManagedObjectExpected
from ..raml.raml import Raml


class Scfc(Raml):
    ANTL = 'ANTL'
    RMOD = 'RMOD'
    SMOD = 'SMOD'
    BBMOD = 'BBMOD'
    CLOCK = 'CLOCK'
    LCELL = 'LCELL'
    LNBTS = 'LNBTS'
    LNCEL = 'LNCEL'
    MRBTS = 'MRBTS'
    SECADM = 'SECADM'
    CABLINK = 'CABLINK'

    CMDATA_PATH = '{*}cmData'
    ALL_MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject'
    MANAGED_OBJECT_PATH = CMDATA_PATH + '/{*}managedObject[@distName="{dist_name}"]'
    MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject[@class="{managed_object_class}"]'

    def set_bts_id(self, bts_id):
        """Sets correct btsId in all objects"""
        for managed_object in self.find_single_managed_object(self.LNBTS), self.find_single_managed_object(self.MRBTS):
            self.change_managed_object_id_globally(managed_object, bts_id)

        for managed_object in self.find_all_managed_objects():
            self._update_bts_id_params(managed_object, bts_id)

    def _update_bts_id_params(self, managed_object, bts_id):
        for bts_id_param in managed_object.find_params('btsId'):
            bts_id_param.value = bts_id
        for list_param in managed_object.find_all_list_params():
            for bts_id_param in list_param.find_params('btsId'):
                bts_id_param.value = bts_id

    def set_bts_name(self, bts_name):
        """Sets BTS name"""
        for mo_name, param_name in [(self.MRBTS, 'btsName'), (self.LNBTS, 'eNBName'), ('BTSSCL', 'btsName')]:
            if self.has_managed_object(mo_name):
                mo = self.find_single_managed_object(mo_name)
                if mo.has_param(param_name):
                    mo.find_param(param_name).value = bts_name.replace('_', '-')

    def set_trs_ip(self, trs_ip):
        """Sets TRS IP as localIpAddr and bfdDestIpAddr"""
        for mo_name, param_name in [('IPADDRESSV4', 'localIpAddr'), ('BFD', 'bfdDestIpAddr')]:
            try:
                self.find_single_managed_object(mo_name).find_param(param_name).value = trs_ip
            except (NoSuchManagedObject, NoSuchParameter, NoSuchListParameter):
                pass

    def set_oam_ip(self, oam_ip):
        """Sets OAM IP as oamPeerIpAddress"""
        try:
            self.find_single_managed_object('MPLANENW').find_param('oamPeerIpAddress').value = oam_ip
        except (NoSuchManagedObject, NoSuchParameter, NoSuchListParameter, ExactlyOneManagedObjectExpected):
            pass

    def set_gateway(self, trs_ip):
        """Sets gateway in IPRT manage object"""
        try:
            for mo_name, list_name in [("IPRT", "staticRoutes"), ("IPRT_R", "forwardingEntries")]:
                self.find_single_managed_object(mo_name).find_list_param(list_name).find_param("gateway").value = \
                    self._calculate_default_gateway(trs_ip)
        except (NoSuchManagedObject, NoSuchParameter, NoSuchListParameter, ExactlyOneManagedObjectExpected):
            pass

    def _calculate_default_gateway(self, trs_ip):
        """Because there is no way to take gateway in explicit way it will be calculate based on TRS IP Address.
           In UTE project this is TRS_IP - 1 e.g. 10.0.0.4 - 1 = 10.0.0.3
        """
        last_octet = int(trs_ip[-1])
        if last_octet > 0:
            return '10.0.1.{}'.format(last_octet - 1)
        return '10.0.1.1'

    def set_logical_cell_ids(self, cell_ids):
        """Sets the logical cell ids. This parameter is stored in LCELL ids and LNCEL.lcrId"""
        sorted_lncels = sorted(self.find_managed_objects(self.LNCEL), key=lambda mo: mo.id)
        sorted_lcells = sorted(self.find_managed_objects(self.LCELL), key=lambda mo: mo.id)
        self._ensure_cell_counts_match(cell_ids, sorted_lncels)
        self._ensure_cell_counts_match(cell_ids, sorted_lcells)
        for new_id, lcell, lncel in zip(cell_ids, sorted_lcells, sorted_lncels):
            lncel.find_param('lcrId').value = new_id
            self.change_managed_object_id_globally(lcell, new_id)

    def set_physical_cell_ids(self, cell_ids):
        """Sets the physical cell ids. This parameter is stored in LNCEL.phyCellId"""
        lncel_mos = self.find_managed_objects(self.LNCEL)
        self._ensure_cell_counts_match(cell_ids, lncel_mos)
        sorted_mos = sorted(lncel_mos, key=lambda mo: mo.id)
        for new_id, lncel_mo in zip(cell_ids, sorted_mos):
            lncel_mo.find_param('phyCellId').value = new_id

    def _ensure_cell_counts_match(self, cell_ids, lncel_mos):
        if len(cell_ids) != len(lncel_mos):
            raise ScfcFixerException('Attempting to set ids for {} cells while there are {} cells in the SCFC'
                                     .format(len(cell_ids), len(lncel_mos)))

    def remove_all_managed_obejcts_except_first(self, managed_objects_class):
        """Removes all ManagedObjects except the first which has the lowest id vale"""
        [mo.remove() for mo in sorted(self.find_managed_objects(managed_objects_class), key=lambda m: m.id)[1:]]

    def _count_fbba(self, bbmods):
        return len([bbmod for bbmod in bbmods if bbmod.type == 'FBBA'])

    def _remove_srio_connection_list(self, index):
        bbmod = self.find_managed_object(self.BBMOD, index)
        if bbmod.has_list_param("srioConnectionList"):
            bbmod.find_list_param("srioConnectionList").remove()

    def adjust_bbmods(self, bbmods):
        """Adjust the number and types of BBMODs and all related parameters."""
        self.adjust_managed_objects_count(self.BBMOD, len(bbmods))
        for index, bbmod in enumerate(bbmods, start=1):
            self._modify_bbmod(index, bbmod)
        for index in range(1, self._count_fbba(bbmods) + 1):
            self._remove_srio_connection_list(index)

    def _modify_bbmod(self, index, bbmod):
        bbmod_mo = self.find_managed_object(self.BBMOD, index)
        if bbmod_mo.has_param('serNum'):
            bbmod_mo.find_param('serNum').value = self._get_bbmod_serial(bbmod.type, index)
            bbmod_mo.find_param('prodCode').value = self._get_bbmod_product_code(bbmod)
            bbmod_mo.find_param('sModPort').value = index
        bbmod_mo.find_param('prodCodePlanned').value = self._get_bbmod_product_code(bbmod)

    def adjust_radios(self, radios):
        """Adjust the number and types of RMODs and all related parameters."""
        self.adjust_managed_objects_count(self.RMOD, len(radios))
        for index, radio in enumerate(radios, start=1):
            self._modify_rmod(index, radio.bbmod_id, radio.link_id, radio.type)

    def _modify_rmod(self, index, bbmod_id, link_id, name='FXEA'):
        """Adds a new RMOD managed object with given index and all necessary parameters consistent with this index and given number of FBIPs"""
        rmod_mo = self.find_managed_object('RMOD', index)
        rmod_mo.add_param_or_set_value_in_existing('productName', name)
        rmod_mo.add_param_or_set_value_in_existing('serNum', 'K911470576{}'.format(index))
        if rmod_mo.has_list_param('connectionList'):
            conn_list = rmod_mo.find_list_param('connectionList')
            conn_list.add_param_or_set_value_in_existing('linkId', link_id)
            conn_list.add_param_or_set_value_in_existing('positionInChain', 1)
            conn_list.add_param_or_set_value_in_existing('bbModId', bbmod_id)

    def _get_bbmod_product_code(self, bbmod):
        if bbmod.type == 'FBBA':
            return '472182A.101'
        elif bbmod.type == 'FBBC':
            return '472797A.101'
        elif bbmod.type == 'FBIP':
            return '473096A.{}'.format(bbmod.hw_version)
        else:
            raise ValueError('Unknown BBMOD: {}. Only FBBA,FBBC and FBIP are supported.'.format(bbmod.type))

    def _get_bbmod_serial(self, bbmod_type, index):
        if bbmod_type in ('FBBA', 'FBBC'):
            return self._get_bbmod_serial_for_fsmr3(bbmod_type, index)
        elif bbmod_type == 'FBIP':
            return self._get_bbmod_serial_for_fsmr4(index)
        else:
            raise ValueError('Unknown BBMOD: {}. Only FBBA, FBBC and FBIP are supported.'.format(bbmod_type))

    def _get_bbmod_serial_for_fsmr3(self, bbmod_type, index):
        if bbmod_type == 'FBBA':
            return 'L6131824303'
        elif bbmod_type == 'FBBC' and index == 1:
            return 'L1142534099'
        elif bbmod_type == 'FBBC' and index == 2:
            return 'L1142506383'
        else:
            raise ValueError('Invalid BBMOD id: {}. Only ids 1 and 2 are supported.'.format(id))

    def _get_bbmod_serial_for_fsmr4(self, index):
        if index in [1, 2, 3]:
            return 'L915290011{}'.format(index)
        else:
            raise ValueError('Invalid BBMOD id: {}. Only ids 1, 2 and 3 are supported.'.format(id))

    def _get_bbmod_product_name(self, bbmod_type):
        if bbmod_type == 'FBBA':
            return 'Flexi Baseband Sub-Module FBBA'
        elif bbmod_type == 'FBBC':
            return 'Flexi Baseband Sub-Module FBBC'
        elif 'FBIP' in bbmod_type:
            return 'Flexi Baseband Sub-Module FBIP'
        else:
            raise ValueError('Unknown BBMOD: {}. Only FBBA, FBBC and FBIP are supported.'.format(bbmod_type))

    def adjust_bbmod_cablinks(self, bbmods):
        """Removes all CABLINKs pointed to not exising BBMOD."""
        bbmods_count = len(bbmods)
        if bbmods_count < 2:
            self._remove_bbmod_cablinks('BBMOD-2')
        if bbmods_count < 1:
            self._remove_bbmod_cablinks('BBMOD-1')

    def _remove_bbmod_cablinks(self, *bbmod_names):
        for cablink in self.find_managed_objects(self.CABLINK):
            param = cablink.find_param("secondEndpointDN")
            if any(name in param.value for name in bbmod_names):
                cablink.remove()

    def adjust_managed_objects_count(self, managed_objects_class, number, new_ids=None):
        """Method removes all managed objects except first and clone it according to number param"""
        if new_ids and len(new_ids) != number:
            raise ValueError("Mismatch length of new_ids and number parameter, {}=/={}.".format(len(new_ids), number))

        if number == 0:
            [mo.remove() for mo in self.find_managed_objects(managed_objects_class)]
            return

        self.remove_all_managed_obejcts_except_first(managed_objects_class)
        source_mo = self.find_single_managed_object(managed_objects_class)

        new_ids = new_ids if new_ids else range(source_mo.id, source_mo.id+number)
        source_mo.id = new_ids[0]
        for new_id in new_ids[1:]:
            source_mo.clone(new_id)
